const AddVoucher  = ({ data, confirm, updateView }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);

	const navigate = useNavigate();

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			updStore("accountPicker", null);
			updStore("productListOnVoucherCmp", null);
			updStore("productList2VoucherSelected", null);
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};

	const printInvLbs = async () => {
		updStore("bluePrint",null)
		let frm2 = getStore(frmNm) || {};

		let obj2Prnt = {
			invoice: frm2?.invoice,
			date: frm2?.date,
			clientAddress: frm2?.clientAddress,
			clientName: frm2?.clientName,
			products: []
		}

		
		let date = (new Date()).getTime()+800;
		if(obj2Prnt["date"]){
			let nn = (new Date(obj2Prnt["date"])).getTime();
			date = nn?nn:date;
		}
		obj2Prnt["date"] = date; 



		const promises = getStore(productListOn) && getStore(productListOn).map(async (item) => {
			let productD = getStore("products_ids")?.[item?.productId];
			let nOvj = {}
			nOvj["productName"] = productD?.name;
			nOvj["qty"] = item?.qty*1;
			nOvj["profile"] = item?.profile;
			if(item?.bluePrint?.type){
				let gg = document.getElementById(item.productId +"_"+ item?.bluePrint?.type);
				let dataUrl = await htmlToImage.toPng(gg);
				
				nOvj["pngId"] = dataUrl;
			}
			obj2Prnt.products.push(nOvj);
		})
		const contents = await Promise.all(promises);
		//console.log(JSON.stringify(obj2Prnt))

		// console.log(JSON.stringify(getStore(productListOn)))
	
		let pdfUri = await VoucherPdf(obj2Prnt);


		//console.log(ffm);
		//let pdfUri = await generateTemp("I485_form.pdf", 1)
		// setLoadPrint(false)
		window.open(pdfUri);
	}

	const save  = async ()  => {
		updStore("bluePrint",null)
		let frm2 = getStore(frmNm) || {};

		let obj2Prnt = {
			invoice: frm2?.invoice,
			date: frm2?.date,
			clientAddress: frm2?.clientAddress,
			clientName: frm2?.clientName,
			products: []
		}

		
		let date = (new Date()).getTime()+800;
		if(obj2Prnt["date"]){
			let nn = (new Date(obj2Prnt["date"])).getTime();
			date = nn?nn:date;
		}
		obj2Prnt["date"] = date; 
		obj2Prnt["products"] = getStore(productListOn); 
		obj2Prnt["voucherId"] = gen16CodeId(); 
		obj2Prnt["voucherStatus"] = 2; 
		


		if(updateView){

		}else{
			let bdyq2 = {...getStore(qryStore())?.add_voucher_production};
			bdyq2.params = {
				businessId:  getStore("profileUser")?.businessId
			}
			bdyq2.form=obj2Prnt;
			const res = fetchEncryptStream(bdyq2);
			const td = await res;
			
			if (td) {
				//Log$$(td)
			}
		}
		
		
		 
		
		data?.modalID && CloseModal({id:data?.modalID});
		
		setTimeout(() => {
			updStore(productListOn, null);
			updStore("provider_picker", null);
			updStore(frmNm, null)
			set_obs(gen16CodeId());
			confirm && confirm();
		}, 400);


	}

	

	//let accountD = getStore("account_ids")?.[getStore("accountPicker")?.account];
	//let subaccountD = getStore("sub_account_ids")?.[getStore("accountPicker")?.subAccount];
	


	return (
		<div style={{
			maxHeight: "96vh",
			minHeight:  "93vh",
			width: "1060px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					Crear Voucher
				</p>
				<div className="flexSpace"/>
				<p className="label">Invoice</p>
				<div className="date2Upd" style={{padding: 7, fontSize:18}}>{getStore(frmNm)?.["invoice"]}</div>
				
			</div>

			<div className="_dsplFlx ">
				<DateCalComponent init={getStore(frmNm)?.["date"]} updDate={(e)=>updFrm("date",e)} />
               

				<div className="flexSpace"/>
				
			</div>
			
			
	
			<ProductsBox />

			<div className="_dsplFlx "  style={{margin: "18px 0"}}>
				<TextInput  
					init={getStore(frmNm)?.["clientName"]} 
					label={"Nombre Cliente"} 
					width={520} 
					updChanges={(e)=>updFrm("clientName",e)}
				/>
			</div>
			<div className="_dsplFlx "  style={{margin: "18px 0"}}>
				<TextInput  
					init={getStore(frmNm)?.["clientAddress"]} 
					label={"Direccion"} 
					width={520} 
					updChanges={(e)=>updFrm("clientAddress",e)}
				/>
			</div>

		
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				<div className="card">
					<button onClick={save}>
						{updateView?"Actualizar":"Guardar"}
					</button>
				</div>
			</div>
		

			<div className={"rndImghidde"}>
				{getStore(productListOn) && getStore(productListOn)?.map((item, indE)=>{
					const Cmp2Rend = {
							"LL": <LeftLShapeScketch  item={item} svDm={item?.bluePrint} addBlPr={()=>{}} profile={item?.profile} />,
							"U":<UShapeScketch item={item} svDm={item?.bluePrint} addBlPr={()=>{}} profile={item?.profile}/>
					}
					if(!(item?.bluePrint?.type)){
						return null
					}
					return  (Cmp2Rend[item?.bluePrint?.type]);
				})}
			</div>
			
		</div>
	);
};

