const ProductsBox = ({}) => {
	const [obs, set_obs] = useState(0);

	const  updObs = () =>{
		set_obs(gen16CodeId())
    }
	

    const  clear = (v) =>{
        updStore("product_picker_in", null);
		set_obs(gen16CodeId())
    }
	
	const  handlePick = (v) =>{
		let nn= {
			"productId":v.productId,
			"unit": v.unit
		}
		updStore("product_picker_in", nn);
		set_obs(gen16CodeId())
	}


	let productD = getStore("products_ids")?.[getStore("product_picker_in")?.productId];
	
	
	const updFrmProducts = (f, v, k) => {
		let frm2 = getStore("product_picker_in") || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore("product_picker_in", frm2);
		set_obs(gen16CodeId())
	};

	const addProduct2List = () => {
		let frm2 = {...getStore("product_picker_in")} || {};
		let rstFrm = {...getStore("product_picker_in")} || {};
		let productListOnCmp = getStore(productListOn) || [];

		if(frm2.dimension){
			frm2["qty"]  = 1;
			frm2["squareFeet"] = calcSf2fromInch(frm2?.dimension.split(",")[0], frm2?.dimension.split(",")[1]);
			frm2["pricePerSquareFeet"] = frm2["price"]*1 / frm2["squareFeet"]*1;
		}
		
		let date =    (new Date()).getTime()+800;
		if(getStore(frmNm)?.["date"]){
			let nn = (new Date(getStore(frmNm)["date"])).getTime();
			date = nn?nn:date;
		}
		frm2["date"] = date; 
		productListOnCmp.push(frm2)
		//let id = frm2["productId"];
		//productListOnCmp[id] = frm2;
		updStore(productListOn, productListOnCmp);

		rstFrm["productId"] = null;
		rstFrm["qty"] = "";
		rstFrm["price"] = "";
		updStore("product_picker_in", rstFrm);
		set_obs(gen16CodeId())
	}

	const rmvProduct2List = (inDx) => {
		let productListOnCmp = getStore(productListOn) || [];
		// delete productListOnCmp[id];
		productListOnCmp.splice(inDx, 1)
		updStore(productListOn, productListOnCmp);
		set_obs(gen16CodeId())
	}

	const printInvLbs = () => {
		
	}

	let productListSelected = getStore(productListSelectedCollection) || {};

	const deleteSelected = () => {
		let nC = getStore(productListOn).filter(element=>{
			return !productListSelected[element.inventoryId];
		})
		updStore(productListOn, nC);
		updStore(productListSelectedCollection, {});
		set_obs(gen16CodeId())
	}

	
	const selectAll = () => {

		
		let productListSelected = getStore(productListSelectedCollection) || {};
		if(ObjectKeys(productListSelected).length < getStore(productListOn).length){
			getStore(productListOn).map(element=>{
				productListSelected[element.inventoryId] = 1;
			})
			updStore(productListSelectedCollection, productListSelected);
		}else{
			updStore(productListSelectedCollection, {});
		}
		
		set_obs(gen16CodeId())
	}




	const updlocDrop =  (v) => {
		updFrmProducts("inventoryId",v.id);
		updFrmProducts("alphaCode",v.label);	
	}



	return (
		
		<div className="boxAddAcc" style={{margin: "18px 0"}}>

			{getStore("product_picker_in")?.productId ? 
			<div className="_dsplFlx " style={{margin: "18px 0"}}>
				<div className=" acc_dtls">
					<div className="_dsplFlx"   onClick={clear}>
						<div className="code" style={{color: "#646cff"}}>
							{productD?.upc_barcode} 
						</div>
						<div className="name">
							{productD?.name}
						</div>
					</div>
					<div className="flexSpace"/>
				</div>
			</div> :
			<PickProduct
				width={420}
				handleClick={handlePick}
			/>
			}
			
			{getStore("product_picker_in")?.productId? 
			<div className="_dsplFlx " >
				
				<TextInput  
					init={getStore("product_picker_in")?.["qty"]} 
					label={"Cantidad"} 
					width={100} 
					type={"number"}
					updChanges={(e)=>updFrmProducts("qty",e)}
				/>
				<div className="centerBx" style={{maxWidth: 130 , marginLeft: 17, marginTop: 13}}>
					

					<DropDwnPicker 
						init={getStore("product_picker_in")?.["profile"]}
						lbl_empty={"Profile"} 
						list={[
							{label: "choseOne", id:null},
							{label: "No", id:"-"},
							{label: "FLAT", id:"FLAT"},
							{label: "PENCIL", id:"PENCIL"},
							{label: "BEVEL", id:"BEVEL"},
							{label: "DEMI", id:"DEMI"},
							{label: "OGEE", id:"OGEE"},
							{label: "COBE", id:"COBE"},
							{label: "BULLNOSE", id:"BULLNOSE"}
						]} 
						onSelect={(e)=>updFrmProducts("profile",e.id)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
					/>
				</div>

				
				<div className="_dsplFlx spaceAround centerBx"   style={{maxWidth: 130 , marginLeft: 17, marginTop: 13}}>
				
					<DropDwnPickerSearchComponent
						init={getStore("product_picker_in")?.["inventoryId"]}
						lbl_empty={"Inventory"} 
						func={getInventoryToDrpDwn} 
						onSelect={(e)=>updlocDrop(e)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"280px"}
						extraParam={getStore("product_picker_in")?.["productId"]}
					/>
				</div>
				
				<div className="flexSpace"/>
				
				<div className="centerBx">
					{getStore("product_picker_in")?.qty ? 
					<button onClick={addProduct2List}>
						Agregar
					</button>
					:null}
				</div>
				
			</div>
			:null}
			

			{ ObjectKeys(productListSelected).length>0?
			<div className="_dsplFlx hdr_bar purple" style={{margin: "18px 0"}}>
				<div className="tr_bar tr_bar_5 align_itm">
					<div className="icon align_itm" onClick={selectAll}>
						<Svg name={ ObjectKeys(productListSelected).length < getStore(productListOn).length? "minus-circle-outline": "check_circle_outline"} color={"#646cff"}/>
					</div>
				</div>
				<div className="tr_bar tr_bar_20 align_itm left_alg">
				{ObjectKeys(productListSelected).length} Seleccionado(s)
				</div>
				<div className="tr_bar tr_bar_70">
					
				</div>
				<div className="tr_bar tr_bar_5 align_itm">
					<div className="icon align_itm" onClick={deleteSelected}>
						<Svg name={"outline_delete"} color={"#646cff"}/>
					</div>
				</div>
			</div>
			:
			<div className="_dsplFlx hdr_bar purple align_itm" style={{margin: "18px 0"}}>
				<div className="tr_bar tr_bar_5">
				{getStore(productListOn)?.length? getStore(productListOn)?.length : ""}
				</div>
				<div className="tr_bar tr_bar_50 left_alg">
					Producto
				</div>
				<div className="tr_bar tr_bar_10">
					Inventario
				</div>
				<div className="tr_bar tr_bar_15">
					Qty
				</div>
				<div className="tr_bar tr_bar_15">
					Profile
				</div>
				<div className="tr_bar tr_bar_5">
					
				</div>
			</div>
			}
			{getStore(productListOn)  && getStore(productListOn).length > 0  && 
				getStore(productListOn)?.map((element, indE)=>
				<ListingProducts 
					key={element.productId +"_"+ indE} 
					idKey={element.productId}
					index={indE} 
					data={element} 
					deleteItem={rmvProduct2List}
					updObs={updObs}
				/>
			)}
		</div>

	)
}



const calcSf2fromInch = (w,h) =>{
	let square_inch = w*h* 0.0069444444444;
	return parseFloatToDecimal(square_inch,2);
};


const ListingProducts  = ({ data, deleteItem, updObs, index }) => {


	const [selected, setSelected] = useState(false);

	let productD = getStore("products_ids")?.[data?.productId];
	
	let dim = data?.dimension && data?.dimension.split(",")[0] +" X " + data?.dimension.split(",")[1];
	
	let dimenss =  data?.dimension && {
		lbl: dim + " (inch)",
		hover: data?.squareFeet + "S/F X $" +  parseFloatToDecimal(data?.pricePerSquareFeet,2)
	};



	// const hoverRef = useRef(false);
	const overCompRef = useRef(null);

	const drawBox=(e)=>{
		
		// overCompRef?.current?.setAttribute("data-ved",e);
		overCompRef?.current?.showw(e);
		
	}

	const bluePrintIsle = () => {
		closeMenu()
	}

	const bluePrintL = () => {
		
		updObs();
		closeMenu()
	}

	const bluePrintMdl = (t) => {
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		modaldata["content"] = <BluePrintModal 
			comp2Render={t}
			confirm={AddBlPr2Prod} 
			item={data}

			
		/>
		OpenModal(modaldata);
		updObs();
		closeMenu()
	}


	const getIndex = (data,productId) => {
		let inD = null;
		data.map((dd,ii)=>{
			if( dd.productId === productId){
				inD = ii;
			}
		})
		return inD;
	}

	const AddBlPr2Prod = (v) => {

		let copyD = {...data};
		
		copyD.bluePrint =v;
		let productListOnCmp = getStore(productListOn);
		let ff = getIndex(productListOnCmp, copyD.productId);
		productListOnCmp[ff] = copyD;
		

		updStore(productListOn, productListOnCmp);
		updObs();
	}




	const makeMultiCopyConfirm = (v) => {
		let productListOnCmp = getStore(productListOn);
		Array.from(Array(v).keys()).map(r=>{
			let copyD = {...data};
			copyD.inventoryId = gen16CodeId();
			copyD.alphaCode = genAlphCode();
			productListOnCmp.push(copyD);
		})
		updStore(productListOn, productListOnCmp);
		updObs();
		closeMenu()
	}


	const makeMultiCopy = () => {

		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		modaldata["content"] = <MultiCopiesAlert label={"Copias Multiples"}
		 //confirm={makeMultiCopyConfirm} 
		item={data} />
		OpenModal(modaldata);
		
	}

	


	const openMenu = () => {
		updStore("bluePrint",null)
		if(data?.bluePrint){
			bluePrintMdl(data?.bluePrint.type);
		}else{
			
			drawBox(true)
		}
	}



	const closeMenu = () => {
		drawBox(false)
	}

	const handleSelect = () => {
		
		let productListSelected = getStore(productListSelectedCollection) || {};
		if(productListSelected[data.inventoryId]){
			delete productListSelected[data.inventoryId];
		}else{
			productListSelected[data.inventoryId] = 1;
		}
		updStore(productListSelectedCollection, productListSelected);
		//setSelected(!selected);
		updObs();
	}

	let productListSelected = getStore(productListSelectedCollection) || {};
	
	return (
		<div className="_dsplFlx hdr_bar centerBx">
			<div className="tr_bar tr_bar_5 icon " onClick={handleSelect}>
				<Svg name={productListSelected[data.inventoryId]?"check_circle_outline":"radio_unchecked"} color={productListSelected[data.inventoryId]?"var(--hrm_palette-blue-purple)":"var(--hrm_palette-imput-label_gray)"}/>
			</div>
			<div className="tr_bar tr_bar_50 left_alg" >
				{productD?.name}
			</div>
			<div className="tr_bar tr_bar_10 centerBx" style={{marginTop:-4}}>
				{data?.alphaCode}
			</div>
			<div className="tr_bar tr_bar_15 centerBx">
				{parseFloatToDecimal(data?.qty,2)}
			</div>
			<div className="tr_bar tr_bar_15 centerBx">
				{data?.profile}
			</div>
			<div className="flexSpace"/>
			
			<div className=" relPos" >
				<FloatActionBtn 
					ref={overCompRef}
					handleIcon1={()=>bluePrintMdl("LL")}
					handleIcon2={()=>bluePrintMdl("I")}
					handleIcon3={()=>bluePrintMdl("U")}
				/>
				{data?.profile? 
				<div className="icon centerBx" onClick={openMenu}>
					
					<Svg name={"vector-polygon"} color={"var(--hrm_palette-imput-txt_gray)"}/>
				</div>
				:null}
			</div>
			

		</div>
	)

}







