
import React, { useState } from "react";

import "./styles.css"
import { CloseModal } from "../../../components/DialogHRM";
import { TextInput_Cmpt } from "../../../components";

const TextInput = TextInput_Cmpt();



const MultiCopiesAlert  = ({ data, confirm, label, close }) => {

	const [copies, setCopies ] = useState(0);

	const { modalID } = data;

	const handleClose =  (v) => {
		CloseModal({id:modalID})
    }
    
    const handleConfirm =  () => {
		
        confirm(copies*1);
		handleClose();
	}



    return (
       
		<div style={{
			maxHeight: "40vh",
			minHeight:  "28vh",
			overflow: "auto",
			background: "#fff",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					{label}
				</p>
				<div className="flexSpace"/>
				
			</div>
			<div className="_dsplFlx ">
				<span>
					Cuantas copias deseas hacer 
				</span>
			</div>
			<div className="_dsplFlx " style={{padding:"15px 10px 0"}}>
				<div className="flexSpace"/>
				<TextInput  
					init={copies} 
					width={100} 
					type={"number"}
					updChanges={(e)=>setCopies(e*1)}
				/>
				<div className="flexSpace"/>
			</div>
			<div className="_dsplFlx " style={{padding:"15px 10px"}}>
				<div className="flexSpace"/>
				<p className="group_title addBtn" onClick={handleClose}>
					Cancelar
				</p>
				<p className="group_title addBtn " onClick={handleConfirm}>
					Crear Copias
				</p>
			</div>

		</div>
    )   
}

export default MultiCopiesAlert;


